import { HonoRequest } from '../clone/src/request'

const mk = (body: BodyInit, headers?: Record<string, string>) =>
  new HonoRequest(new Request('http://localhost/', { method: 'POST', body, headers }))

async function run(name: string, fn: () => Promise<unknown>) {
  try {
    console.log(name, 'OK', JSON.stringify(await fn()))
  } catch (e) {
    console.log(name, 'ERR', (e as Error).message)
  }
}

const fd = () => {
  const f = new FormData()
  f.append('foo', 'bar')
  return f
}

await run('multipart: formData() then parseBody()', async () => {
  const req = mk(fd())
  await req.formData()
  return req.parseBody()
})

await run('urlencoded: formData() then parseBody()', async () => {
  const req = mk(new URLSearchParams({ foo: 'bar' }))
  await req.formData()
  return req.parseBody()
})

await run('multipart: parseBody() then formData()', async () => {
  const req = mk(fd())
  await req.parseBody()
  return (await req.formData()).get('foo')
})

await run('multipart: parseBody() twice', async () => {
  const req = mk(fd())
  await req.parseBody()
  return req.parseBody()
})

await run('multipart: text() then parseBody()', async () => {
  const req = mk(fd())
  await req.text()
  return req.parseBody()
})

await run('multipart: parseBody() then text() length', async () => {
  const req = mk(fd())
  await req.parseBody()
  return (await req.text()).length > 0
})

await run('bodyCache keys after parseBody', async () => {
  const req = mk(fd())
  await req.parseBody()
  return Object.keys(req.bodyCache)
})

